sp_page.css:
/* =========================================================
   MEALCARE — DASHBOARD PAGE CSS
   Shared by Student / Staff / Admin / Manager
   Removes default ServiceNow page spacing
   ========================================================= */

html,
body {
  margin: 0 !important;
  padding: 0 !important;

  width: 100% !important;
  max-width: none !important;

  background: #F8FAFC !important;
  color: #0F172A;

  font-family:
    "Segoe UI",
    Arial,
    sans-serif;

  overflow-x: hidden !important;

  -webkit-font-smoothing: antialiased;
}


/* =========================================================
   SERVICENOW PAGE RESET
   ========================================================= */

body,
.sp-page-root,
.page,
.main-content,
.sp-content,
.sp-page-root .container,
.sp-page-root .container-fluid {
  margin: 0 !important;
  padding: 0 !important;

  width: 100% !important;
  max-width: none !important;

  background: #F8FAFC !important;
}


/* =========================================================
   REMOVE DEFAULT SERVICENOW ROW SPACING
   ========================================================= */

.sp-page-root .row,
.main-content .row {
  margin-left: 0 !important;
  margin-right: 0 !important;
}


/* =========================================================
   REMOVE COLUMN PADDING
   ========================================================= */

.sp-page-root [class*="col-"],
.main-content [class*="col-"] {
  padding-left: 0 !important;
  padding-right: 0 !important;
}


/* =========================================================
   DASHBOARD WIDGET AREA
   ========================================================= */

.campus-header,
.student-dashboard,
.staff-dashboard,
.admin-dashboard,
.manager-dashboard {
  box-sizing: border-box;
}


/* =========================================================
   GLOBAL BOX SIZING
   ========================================================= */

.campus-header *,
.campus-header *::before,
.campus-header *::after,

.student-dashboard *,
.student-dashboard *::before,
.student-dashboard *::after,

.staff-dashboard *,
.staff-dashboard *::before,
.staff-dashboard *::after,

.admin-dashboard *,
.admin-dashboard *::before,
.admin-dashboard *::after,

.manager-dashboard *,
.manager-dashboard *::before,
.manager-dashboard *::after {
  box-sizing: border-box;
}


/* =========================================================
   PAGE BACKGROUND
   ========================================================= */

.sp-page-root {
  min-height: 100vh;
  background: #F8FAFC !important;
}


/* =========================================================
   REMOVE SERVICE NOW TOP / BOTTOM GAPS
   ========================================================= */

.sp-page-root > .container,
.sp-page-root > .container-fluid,
.sp-page-root > .row {
  margin-top: 0 !important;
  margin-bottom: 0 !important;
}


/* =========================================================
   SCROLLBAR
   ========================================================= */

::-webkit-scrollbar {
  width: 8px;
}

::-webkit-scrollbar-track {
  background: #F1F5F9;
}

::-webkit-scrollbar-thumb {
  background: #94A3B8;
  border-radius: 20px;
}

::-webkit-scrollbar-thumb:hover {
  background: #2563EB;
}


/* =========================================================
   SELECTION
   ========================================================= */

::selection {
  background: #2563EB;
  color: #FFFFFF;
}


/* =========================================================
   ACCESSIBILITY
   ========================================================= */

a:focus-visible,
button:focus-visible {
  outline: 3px solid #60A5FA !important;
  outline-offset: 3px;
  border-radius: 6px;
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 767px) {

  html,
  body {
    width: 100% !important;
    max-width: none !important;
  }

  .sp-page-root,
  .main-content,
  .sp-content {
    width: 100% !important;
    max-width: none !important;
  }

}


/* =========================================================
   REDUCED MOTION
   ========================================================= */

@media (prefers-reduced-motion: reduce) {

  html {
    scroll-behavior: auto !important;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

}
